/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, And, Mul, Pow, Rational, Relational, Sym, bsplineBasis, bsplineBasisSet, interpolatingSpline, piecewise } from '../../../src';
import { at, sympyStr } from '../../sympy-str';
import { equivalent } from '../../sympy-equivalent';

describe("doctests of sympy.functions.special.bsplines", () => {
  it("bspline_basis(d, knots, 0, x)", () => {
    const x = new Sym('x');
    expect(sympyStr(bsplineBasis(Rational.of(0n, 1n, { gcd: 1n }), [0, 1, 2, 3, 4], Rational.of(0n, 1n, { gcd: 1n }), x))).toBe('Piecewise((1, (x >= 0) & (x <= 1)), (0, True))');
  });
  it("bspline_basis(3, tuple(range(5)), 0, x)", () => {
    const x = new Sym('x');
    expect(sympyStr(bsplineBasis(Rational.of(3n, 1n, { gcd: 1n }), [0, 1, 2, 3, 4], Rational.of(0n, 1n, { gcd: 1n }), x))).toBe('Piecewise((x**3/6, (x >= 0) & (x <= 1)), (-x**3/2 + 2*x**2 - 2*x + 2/3, (x >= 1) & (x <= 2)), (x**3/2 - 4*x**2 + 10*x - 22/3, (x >= 2) & (x <= 3)), (-x**3/6 + 2*x**2 - 8*x + 32/3, (x >= 3) & (x <= 4)), (0, True))');
  });
  it("bspline_basis(d, knots, 0, x) (2)", () => {
    const x = new Sym('x');
    expect(sympyStr(bsplineBasis(Rational.of(1n, 1n, { gcd: 1n }), [0, 0, 2, 3, 4], Rational.of(0n, 1n, { gcd: 1n }), x))).toBe('Piecewise((1 - x/2, (x >= 0) & (x <= 2)), (0, True))');
  });
  it("interpolating_spline(1, x, [1, 2, 4, 7], [3, 6, 5, 7])", () => {
    const x = new Sym('x');
    expect(sympyStr(interpolatingSpline(Rational.of(1n, 1n, { gcd: 1n }), x, [1, 2, 4, 7], [3, 6, 5, 7]))).toBe('Piecewise((3*x, (x >= 1) & (x <= 2)), (7 - x/2, (x >= 2) & (x <= 4)), (2*x/3 + 7/3, (x >= 4) & (x <= 7)))');
  });
  it("interpolating_spline(3, x, [-2, 0, 1, 3, 4], [4, 2, 1, 1, 3])", () => {
    const x = new Sym('x');
    expect(sympyStr(interpolatingSpline(Rational.of(3n, 1n, { gcd: 1n }), x, [-2, 0, 1, 3, 4], [4, 2, 1, 1, 3]))).toBe('Piecewise((7*x**3/117 + 7*x**2/117 - 131*x/117 + 2, (x >= -2) & (x <= 1)), (10*x**3/117 - 2*x**2/117 - 122*x/117 + 77/39, (x >= 1) & (x <= 4)))');
  });
  it("splines", () => {
    const x = new Sym('x');
    const v1 = bsplineBasisSet(Rational.of(2n, 1n, { gcd: 1n }), [0, 1, 2, 3, 4], x);
    expect(sympyStr([at(v1, 0), at(v1, 1)])).toBe('[Piecewise((x**2/2, (x >= 0) & (x <= 1)), (-x**2 + 3*x - 3/2, (x >= 1) & (x <= 2)), (x**2/2 - 3*x + 9/2, (x >= 2) & (x <= 3)), (0, True)), Piecewise((x**2/2 - x + 1/2, (x >= 1) & (x <= 2)), (-x**2 + 5*x - 11/2, (x >= 2) & (x <= 3)), (x**2/2 - 4*x + 8, (x >= 3) & (x <= 4)), (0, True))]');
  });
});

